def suspeitos(linhas, limite=5):
    contagem = {}
    primeira = {}

    for linha in linhas:
        partes = linha.split()
        if len(partes) < 4 or partes[2] != "FALHA":
            continue
        hora, ip = f"{partes[0]} {partes[1]}", partes[3]

        contagem[ip] = contagem.get(ip, 0) + 1
        if ip not in primeira:
            primeira[ip] = hora

    return {ip: (n, primeira[ip]) for ip, n in contagem.items() if n > limite}

def normalizar_email(email):
    if not email or "@" not in email:
        return None

    email = email.strip().lower()
    usuario, _, dominio = email.partition("@")

    if not usuario or "." not in dominio:
        return None

    if dominio == "gmail.com":
        usuario = usuario.split("+")[0]

    return f"{usuario}@{dominio}"
